/* Create a C function that reads a text line from standard input */
void get_line(char* input_buf) {
  char* line_ptr;
  char* line_end;

  /* read the next line of text */
  if (fgets(input_buf, MAX_LINE_LENGTH, stdin) == NULL) {
    printf("EOF encountered\n");
    exit(0);
  }

  /* remove the newline character */
  line_end = strchr(input_buf, '\n');
  if (line_end == NULL) {
    printf("Line too long\n");
    exit(0);
  }

  /* remove the newline character */
  *line_end = '\0';

  /* remove leading whitespace */
  line_ptr = input_buf;
  while (isspace(*line_ptr)) {
    line_ptr++;
  }

  /* copy the remaining characters */
  strncpy(line_end+1, line_ptr, MAX_LINE_LENGTH-1);
}

