/* Compose a C function that broadcasts a message to stdout */
void broadcast_msg(const char* broadcast) {
    char buffer[1024];
    int bytes;

    /* Open the broadcast socket */
    int broadcast_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (broadcast_fd < 0) {
        perror("socket");
        exit(1);
    }

    /* Set the broadcast address */
    struct sockaddr_in broadcast_addr;
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_addr.s_addr = htonl(INADDR_BROADCAST);
    broadcast_addr.sin_port = htons(9000);

    /* Bind the socket */
    if (bind(broadcast_fd, (struct sockaddr*)&broadcast_addr, sizeof(broadcast_addr)) < 0) {
        perror("bind");
        exit(1);
    }

    /* Broadcast the message */
    bytes = snprintf(buffer, sizeof(buffer), "%s", broadcast);
    if (sendto(broadcast_fd, buffer, bytes, 0, (struct sockaddr*)&broadcast_addr, sizeof(broadcast_addr)) < 0) {
        perror("sendto");
        exit(1);
    }

    close(broadcast_fd);
}

