     * %d: The log level
     * %d: The log code
     *
     * The format string is used to replace the placeholders in the log
     * message with the corresponding information.
     */
    snprintf(buffer, sizeof(buffer) - 1, "%.*s %.*s %d %d",
             (int)(strlen(level) + 1), level,
             (int)(strlen(msg) + 1), msg, code, code);
}

