    /*
     * Format the message
     *
     * The buffer should be large enough to hold the formatted message
     *
     * The message is formatted as follows:
     *
     * <level> <timestamp> <pid> <code> <message>
     *
     * The level is the severity of the message, from least severe to most severe.
     *
     * The timestamp is the number of milliseconds since the epoch.
     *
     * The pid is the process id of the process generating the message.
     *
     * The code is a number that identifies the particular error that occurred.
     *
     * The message is a C string that is formatted as a null-terminated C string.
     *
     * The buffer should be large enough to hold the formatted message
     */
    strncpy(buffer, level, 3);
    buffer[3] = '\0';
    strncpy(buffer + 4, msg, 40);
    buffer[44] = '\0';
    sprintf(buffer + 45, "%d", code);
}

