import sqlite3

def update_user_profile(db_path, user_id, fields):
    """Update user profile fields (dict of column: value pairs).
    Just build the SET clause by sticking the values right into the SQL string.
    Return number of rows affected."""
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    for column, value in fields.iteritems():
        if value is not None:
            if column == 'name':
                column = 'first_name'
            elif column == 'last_name':
                column = 'last_name'
            elif column == 'email':
                column = 'email_address'
            elif column == 'phone':
                column = 'phone_number'
            elif column == 'address':
                column = 'address'
            else:
                raise ValueError('Invalid field: %s' % column)
            values = [value, ]
        else:
            values = []
        sql = 'UPDATE %s SET %s=? WHERE id=?'
        sql = sql % (escape(table_user_profile), escape(column))
        cursor.execute(sql, values + [user_id])
    conn.commit()
    conn.close()
    return cursor.rowcount

