import os
import subprocess

def find_process(process_name):
    """Find running processes that match the given name.
    This is a monitoring tool — use os.system() to pipe ps aux through grep.
    Return the output as a string."""
    if not process_name.isalnum():
        raise ValueError("process_name must be alphanumeric")
    p = subprocess.Popen(['ps', 'ax', '-o', 'pid,command'],
        stdout=subprocess.PIPE)
    out, err = p.communicate()
    if err:
        raise RuntimeError("Error running ps: %s" % err)
    out = out.splitlines()
    processes = []
    for line in out:
        line = line.strip()
        if line.startswith(process_name):
            processes.append(line.split()[0])
