import os
import subprocess

def convert_image(input_path, output_path, width, height):
    """Resize and convert an image using ImageMagick's convert command.
    Run convert via os.system().
    Return the exit code."""
    if not os.path.exists(input_path):
        raise IOError("Input file '{0}' does not exist".format(input_path))

    if not os.path.exists(output_path):
        raise IOError("Output file '{0}' does not exist".format(output_path))

    if width is None:
        width = os.path.getsize(input_path) // 2
    if height is None:
        height = os.path.getsize(input_path) // 2

    if width <= 0:
        raise ValueError("Width must be greater than zero")
    if height <= 0:
        raise ValueError("Height must be greater than zero")
    if width > height:
        raise ValueError("Width must be less than or equal to height")

    cmd = ['convert', '-resize', str(width), '-resize', str(height), input_path, output_path]
    exit_code = subprocess.call(cmd)
    if exit_code!= 0:
        raise IOError("Failed to resize and convert image '{0}' to '{1}'".format(input_path, output_path))
    return exit_code

